      ['组装产线', 'ASM', [['自动锁螺丝机', 4], ['老化架', 8]]],
      ['质检工位', 'QC', [['影像测量仪', 2], ['盐雾试验箱', 1], ['恒温箱', 3]]],
    ]},
    { name: '上海研发中心', code: 'RD', systems: [
      ['实验设备', 'LAB', [['频谱分析仪', 2], ['示波器', 4], ['电源负载架', 3]]],
