      const regionId = nid();
      nodes.push({ id: regionId, type: 'region', name: r.name, code: r.code, parentId: null });
      r.systems.forEach(([sName, sCode, groups]) => {
        const sysId = nid();
        nodes.push({ id: sysId, type: 'system', name: sName, code: r.code + '-' + sCode, parentId: regionId });
