          for (let i = 1; i <= count; i++) {
            const num = String(i).padStart(3, '0');
            nodes.push({
              id: nid(),
              type: 'device',
              name: dName + ' ' + num,
              code: r.code + '-' + sCode + '-' + dCode + '-' + num,
              parentId: sysId,
              status: pickStatus(),
            });
          }
        });
      });
    });

    return { nodes };
  })();
})();

